import {CONSTELLATIONS,STARS,COLLECTIONS,MEMENTOS,hasStar,evolutionQuote,GUILDS,count} from './model.js';
const fmt=n=>Math.floor(n).toLocaleString('en-US');
export function constellationsHTML(s,selected){
 const star=STARS.find(x=>x.id===selected)||STARS[0],owned=hasStar(s,star.id),prerequisite=star.requires&&!hasStar(s,star.requires),canBuy=s.meta.revolutions&&!owned&&!prerequisite&&s.meta.insight>=star.cost&&!s.paused;
 return '<h1 class="page-title">RE-Evolution</h1><section class="constellation-sky"><header class="sky-heading"><div><p class="sky-eyebrow">THE CONSTELLATIONS</p><h2>Carry progress into a new age</h2></div><div class="ep-balance"><strong>'+s.meta.insight+'</strong><span>Evolution Points</span></div></header>'+
 (s.meta.pendingEvolution?'<button class="reward-replay" data-evolution-reveal>View Evolution rewards</button>':'')+
 '<p class="sky-intro">Choose a star to preview its permanent bonus. Follow each constellation from left to right.</p><div class="constellation-tabs" aria-label="Constellations">'+CONSTELLATIONS.map(c=>'<button data-star="'+c.stars[0].id+'" aria-pressed="'+c.stars.some(x=>x.id===star.id)+'">'+c.name.replace('The ','')+'</button>').join('')+'</div><div class="constellation-grid">'+CONSTELLATIONS.map((c,branch)=>'<section class="constellation '+(c.stars.some(x=>x.id===star.id)?'active':'')+'"><h3>'+c.name+'</h3><p>'+c.subtitle+'</p><div class="star-path"><svg viewBox="0 0 300 100" preserveAspectRatio="none" aria-hidden="true"><path d="M48 '+(branch%2?50:80)+' L150 '+(branch%2?80:50)+' L252 '+(branch%2?45:75)+'"/></svg>'+c.stars.map((x,i)=>'<button data-star="'+x.id+'" class="star-node '+(hasStar(s,x.id)?'owned':'')+' '+(star.id===x.id?'selected':'')+'" style="--star-y:'+([branch%2?35:65,branch%2?65:35,branch%2?30:60][i])+'px" aria-pressed="'+(star.id===x.id)+'" aria-label="'+x.name+', '+(hasStar(s,x.id)?'owned':x.cost+' Evolution Points')+'"><span class="star-light" aria-hidden="true">✦</span><span>'+x.name+'</span><small>'+(hasStar(s,x.id)?'Owned':x.cost+' EP')+'</small></button>').join('')+'</div></section>').join('')+'</div>'+
 '<section class="star-detail" aria-live="polite"><div><p class="sky-eyebrow">'+(owned?'PERMANENT BONUS':'SELECTED STAR')+'</p><h3>'+star.name+'</h3><p>'+star.description+'</p>'+(prerequisite?'<p>Requires '+STARS.find(x=>x.id===star.requires).name+'.</p>':'')+'</div><button class="star-buy" data-buy-star="'+star.id+'" '+(!canBuy?'disabled':'')+'>'+(owned?'Star owned':!s.meta.revolutions?'Complete RE-Evolution first':'Buy star · '+star.cost+' EP')+'</button></section></section>'+
 '<section class="evolution-next"><h2>Evolution '+(s.meta.revolutions+1)+' · '+(s.meta.revolutions?'The Renaissance':'The first observation')+'</h2><p>'+(s.meta.revolutions?'Research Guild charters in your Village to unlock economic specializations. Reach the Renaissance, build grand archives, then complete a Celestial Atlas.':'Complete the Great Observatory to earn points and unlock guilds, Renaissance research and the Celestial Atlas in your next civilization.')+'</p></section>'+
 (s.meta.revolutions?'<p class="worker-help">All purchased stars are active from the start of every civilization.</p>':'')+
 (canReady(s)?'<button class="primary" data-reevolve>Review RE-Evolution · '+evolutionQuote(s).total+' EP</button>':'')+
 (Object.values(s.meta.upgrades).some(Boolean)?'<h2>Earlier permanent upgrades</h2><p class="worker-help">Your existing production, storage and research upgrades remain active.</p>':'')+
 '<h2 class="run-history-heading">Completed civilizations</h2>'+(s.meta.history.length?s.meta.history.map(h=>'<div class="run-history-row"><span>Civilization '+h.run+'</span><span>'+Math.floor(h.seconds/3600)+'h '+Math.floor(h.seconds/60%60)+'m · +'+h.reward+' '+(h.currency==='EP'?'EP':'legacy Insight')+'</span></div>').join(''):'<p class="worker-help">Your first completed civilization will appear here.</p>');
}
const canReady=s=>s.wonder.remaining===0&&s.wonder.stage===(s.meta.revolutions?6:4);
export function collectionsHTML(s){
 const q=evolutionQuote(s);
 return '<h1 class="page-title">Collections</h1><p class="worker-summary">'+q.total+' EP on your next completed RE-Evolution</p><p class="worker-help">12 points for completion, '+q.collectionPoints+' for new collection tiers and '+q.itemPoints+' for new mementos. Each tier and memento pays once. Records keep your best single-civilization result, even after a reset. Purchases and refunds do not count as production.</p><div class="collections-grid">'+q.rows.map(row=>{const next=row.thresholds[row.reached];return '<section class="collection-card"><h3>'+row.name+'</h3><p><strong data-collection-value="'+row.id+'">'+fmt(row.value)+'</strong>'+(next?' / '+fmt(next):' · Complete')+'</p><progress aria-label="'+row.name+'" data-collection-progress="'+row.id+'" max="'+(next||row.thresholds.at(-1))+'" value="'+row.value+'"></progress><p>'+row.reached+' / '+row.thresholds.length+' tiers · '+row.claimed+' claimed</p><span class="collection-points">'+(row.points?'+'+row.points+' EP next evolution':next?'Next tier: +'+[1,1,2,3,5][row.reached]+' EP':'All rewards claimed')+'</span></section>';}).join('')+'</div><h2>Mementos</h2><p class="worker-help">Items collected through milestones. Each new discovery awards 1 EP on RE-Evolution.</p><div class="memento-grid">'+MEMENTOS.map((item,i)=>{const owned=s.meta.collections.items.includes(item.id),claimed=s.meta.collections.claimedItems.includes(item.id);return '<section class="memento '+(owned?'found':'')+'"><span class="memento-emblem" aria-hidden="true">'+['♧','▱','⚙','⌖','◒','◉','⬡','✧'][i]+'</span><div><h3>'+item.name+'</h3><p>'+item.description+'</p><small>'+(claimed?'Collected · reward claimed':owned?'Collected · +1 EP next evolution':'Undiscovered')+'</small></div></section>';}).join('')+'</div>';
}
export function guildsHTML(s){
 const enabled=s.meta.revolutions&&s.tech.includes('guildCharters')&&count(s,'guildhall');
 return '<h1 class="page-title">Guilds</h1><p class="worker-help">Choose one specialization for this civilization. Switching is free. Its advantage and tradeoff apply immediately to staffed production and offline progress.</p>'+(!enabled?'<p class="capacity-warning">Research Guild charters and build a guildhall to choose a specialization.</p>':'')+'<div class="guild-grid">'+[{id:'',name:'Independent',description:'No specialization or tradeoff.'},...Object.entries(GUILDS).map(([id,g])=>({id,...g}))].map(g=>'<section class="collection-card"><h3>'+g.name+'</h3><p>'+g.description+'</p><button data-guild="'+g.id+'" '+(!enabled||s.paused||s.guildFocus===(g.id||null)?'disabled':'')+'>'+(s.guildFocus===(g.id||null)?'Active':'Choose guild')+'</button></section>').join('')+'</div>';
}
// Currency is already awarded in the model. Replaying or skipping never changes it.
export function revealEvolution(receipt,{open,finish}){
 open('<div class="evolution-reveal"><p class="sky-eyebrow">CIVILIZATION COMPLETE</p><h2>A new evolution begins</h2><div class="reward-orbit" aria-hidden="true">✦</div><div class="reveal-total"><strong id="evolution-tally">0</strong><span>Evolution Points gained</span></div><ul class="reward-breakdown"><li><span>Completed civilization</span><strong>+'+receipt.base+'</strong></li><li><span>New collection tiers</span><strong>+'+receipt.collectionPoints+'</strong></li><li><span>New mementos</span><strong>+'+receipt.itemPoints+'</strong></li></ul><p>Your points are saved. Spend them on permanent constellation bonuses.</p><div class="dialog-actions"><button id="skip-evolution">Skip animation</button><button class="primary" id="open-constellations">Open constellations</button></div></div>');
 const modal=document.querySelector('#modal');modal.classList.add('evolution-dialog');const tally=document.querySelector('#evolution-tally');
 let elapsed=0,last=performance.now(),frame,stopped=false;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const stop=()=>{stopped=true;cancelAnimationFrame(frame);tally.textContent=receipt.total;};
 const animate=now=>{if(stopped||!tally.isConnected||!modal.open)return;const dt=Math.min(50,now-last);last=now;if(!document.hidden)elapsed+=dt;tally.textContent=Math.floor(receipt.total*Math.min(1,elapsed/3200));if(elapsed<3200)frame=requestAnimationFrame(animate);};
 if(reduced)stop();else frame=requestAnimationFrame(animate);
 modal.addEventListener('close',stop,{once:true});document.querySelector('#skip-evolution').onclick=stop;
 document.querySelector('#open-constellations').onclick=()=>{stop();finish();};
}
